const { createApp } = Vue;

createApp({
  data() {
    return {
      users: []
    };
  },
  mounted() {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => {
        this.users = data;
        console.log('Fetched', data.length, 'users');
      })
      .catch(err => console.error(err));
  },
  template: `
    <div>
      <h1>User Directory</h1>
      <p>Check the console for fetched data</p>
    </div>
  `
}).mount('#root');

