const { createApp } = Vue;

createApp({
  data() {
    return {
      users: [],
      loading: true
    };
  },
  mounted() {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => {
        this.users = data;
        this.loading = false;
      })
      .catch(err => console.error(err));
  },
  template: `
    <div>
      <h1>User Directory</h1>
      <p v-if="loading">Loading...</p>
      <div v-else v-for="u in users" :key="u.id">
        <h3>{{ u.name }}</h3>
        <p>{{ u.email }}</p>
      </div>
    </div>
  `
}).mount('#root');

const { createApp } = Vue;

createApp({
  data() {
    return {
      users: [],
      loading: true,
      error: null
    };
  },
  mounted() {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => {
        this.users = data;
        this.loading = false;
      })
      .catch(err => {
        this.error = err.message;
        this.loading = false;
      });
  },
  template: `
    <div>
      <h1>User Directory</h1>
      <p v-if="loading">Loading...</p>
      <p v-else-if="error" style="color: red">Failed to load users. Please try again.</p>
      <div v-else v-for="u in users" :key="u.id">
        <h3>{{ u.name }}</h3>
        <p>{{ u.email }}</p>
      </div>
    </div>
  `
}).mount('#root');
